public static int countDoubles(int[] numbers) {
    Set<Integer> set = new HashSet<>();
    for (int num : numbers) {
        set.add(num);
    }
    int count = 0;
    for (int num : numbers) {
        if ((num & 1) == 0 && set.contains(num >> 1)) {
            count++;
        }
    }
    return count;
}

public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) return 0;
    java.util.Map<Integer,Integer> freq = new java.util.HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int result = 0;
    for (int num : numbers) {
        if (num == 0) {
            // zeros are twice of zero; count only if at least two zeros exist
            if (freq.get(num) > 1) {
                result++;
            }
        } else if (num % 2 == 0) {
            int half = num / 2;
            if (freq.containsKey(half)) {
                result++;
            }
        }
    }
    return result;
}

