        String a = p[0] + "_" + p[1];
        String b = p[2] + "_" + p[3];
        adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }
    String startKey = start[0] + "_" + start[1];
    String endKey = end[0] + "_" + end[1];
    if (!adj.containsKey(startKey) || !adj.containsKey(endKey)) {
        return "cannot be travelled";
    }
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        for (String neighbor : adj.getOrDefault(cur, java.util.Collections.emptyList())) {
            if (visited.contains(neighbor)) continue;
            if (neighbor.equals(endKey)) return "can be travelled";
            visited.add(neighbor);
            queue.add(neighbor);
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Quick check if start equals end
    if (start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    boolean same = true;
    for (int i = 0; i < n; i++) {
        if (start[i] != end[i]) {
            same = false;
            break;
        }
    }
    if (same) {
        return "can be travelled";
    }

    // Helper to convert coordinate array to a string key
    java.util.function.Function<int[], String> coordToKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path.length != 2 * n) {
            continue; // Skip malformed path
        }
        int[] coord1 = new int[n];
        int[] coord2 = new int[n];
        System.arraycopy(path, 0, coord1, 0, n);
        System.arraycopy(path, n, coord2, 0, n);
        String key1 = coordToKey.apply(coord1);
        String key2 = coordToKey.apply(coord2);
        graph.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
        graph.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
    }

    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);

    // BFS to determine reachability
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = graph.getOrDefault(current, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    int startNode = start[0];
    int endNode = end[0];
    if (startNode == endNode) {
        return "can be travelled";
    }

    // Build adjacency list
    java.util.Map<Integer, java.util.List<Integer>> adjacency = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path == null || path.length < 2) {
            continue;
        }
        int a = path[0];
        int b = path[1];
        adjacency.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        adjacency.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }

    // BFS to find path from startNode to endNode
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    java.util.Set<Integer> visited = new java.util.HashSet<>();

    queue.offer(startNode);
    visited.add(startNode);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        java.util.List<Integer> neighbors = adjacency.getOrDefault(current, java.util.Collections.emptyList());
        for (int neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                if (neighbor == endNode) {
                    return "can be travelled";
                }
                visited.add(neighbor);
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length < 2 || end.length < 2) {
        return "cannot be travelled";
    }
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

    for (int[] p : paths) {
        if (p == null || p.length < 4) continue;
        int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) continue;
        String a = x1 + "," + y1;
        String b = x2 + "," + y2;
        graph.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        graph.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }

    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String curr = queue.poll();
        java.util.List<String> neigh = graph.getOrDefault(curr, java.util.Collections.emptyList());
        for (String next : neigh) {
            if (visited.contains(next)) continue;
            if (next.equals(endKey)) {
                return "can be travelled";
            }
            visited.add(next);
            queue.offer(next);
        }
    }

    return "cannot be travelled";
}

