}

private int dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple) {
    int time = 0;
    for (int child : graph[node]) {
        if (child == parent) continue;
        int sub = dfs(child, node, graph, hasApple);
        if (sub > 0 || hasApple[child]) {
            time += sub + 2; // go to child and back
        }
    }
    return time;
}

