    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int nei : graph[node]) {
            if (parent[nei] == -2) {
                parent[nei] = node;
                stack.push(nei);
            }
        }
    }

    int[] need = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        int node = order[i];
        for (int nei : graph[node]) {
            if (parent[nei] != node) continue;
            if (hasApple[nei] || need[nei] > 0) {
                need[node] += need[nei] + 2;
            }
        }
    }
    return need[0];
}

int dfs(int node) {
    visited[node] = true;
    int time = 0;
    for (int nei: graph[node]) {
      if (!visited[nei]) {
        int childTime = dfs(nei);
        if (childTime > 0 || hasApple[nei]) {
          time += childTime + 2;
        }
      }
    }
    return time;
  }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    int[] time = {0};
    dfs(0, -1, graph, hasApple, time);
    return time[0];
}

private boolean dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple, int[] time) {
    boolean has = hasApple[node];
    for (int nei : graph[node]) {
        if (nei == parent) continue;
        boolean childHas = dfs(nei, node, graph, hasApple, time);
        if (childHas) {
            time[0] += 2;
            has = true;
        }
    }
    return has;
}

public String sortString(String s) {
    int[] freq = new int[256];
    for (int i = 0; i < s.length(); i++) {
        freq[s.charAt(i)]++;
    }
    StringBuilder result = new StringBuilder();
    int remaining = s.length();
    while (remaining > 0) {
        // Step 1: pick smallest character
        char last = 0;
        for (int i = 0; i < 256; i++) {
            if (freq[i] > 0) {
                last = (char) i;
                freq[i]--;
                result.append(last);
                remaining--;
                break;
            }
        }
        // Step 2: pick smallest greater than last
        while (true) {
            boolean found = false;
            for (int i = last + 1; i < 256; i++) {
                if (freq[i] > 0) {
                    last = (char) i;
                    freq[i]--;
                    result.append(last);
                    remaining--;
                    found = true;
                    break;
                }
            }
            if (!found) break;
        }
        if (remaining == 0) break;
        // Step 4: pick largest
        for (int i = 255; i >= 0; i--) {
            if (freq[i] > 0) {
                last = (char) i;
                freq[i]--;
                result.append(last);
                remaining--;
                break;
            }
        }
        // Step 5: pick largest smaller than last
        while (true) {
            boolean found = false;
            for (int i = last - 1; i >= 0; i--) {
                if (freq[i] > 0) {
                    last = (char) i;
                    freq[i]--;
                    result.append(last);
                    remaining--;
                    found = true;
                    break;
                }
            }
            if (!found) break;
        }
    }
    return result.toString();
}

public String sortString(String s) {
    TreeMap<Character, Integer> freq = new TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.put(c, freq.getOrDefault(c, 0) + 1);
    }
    StringBuilder result = new StringBuilder();
    int total = s.length();

    while (result.length() < total) {
        // Ascending phase
        Character cur = freq.firstKey();
        result.append(cur);
        decrement(freq, cur);
        if (result.length() == total) break;

        while (true) {
            Character next = freq.higherKey(cur);
            if (next == null) break;
            result.append(next);
            decrement(freq, next);
            cur = next;
            if (result.length() == total) break;
        }
        if (result.length() == total) break;

        // Descending phase
        cur = freq.lastKey();
        result.append(cur);
        decrement(freq, cur);
        if (result.length() == total) break;

        while (true) {
            Character prev = freq.lowerKey(cur);
            if (prev == null) break;
            result.append(prev);
            decrement(freq, prev);
            cur = prev;
            if (result.length() == total) break;
        }
    }
    return result.toString();
}

private void decrement(TreeMap<Character, Integer> freq, Character key) {
    int count = freq.get(key);
    if (count == 1) {
        freq.remove(key);
    } else {
        freq.put(key, count - 1);
    }
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (char ch : s.toCharArray()) {
        freq[ch - 'a']++;
    }
    StringBuilder sb = new StringBuilder();
    int remaining = s.length();

    while (remaining > 0) {
        // ascending pass
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (freq[i] > 0) {
                sb.append((char) (i + 'a'));
                freq[i]--;
                remaining--;
            }
        }
        // descending pass
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) (i + 'a'));
                freq[i]--;
                remaining--;
            }
        }
    }

    return sb.toString();
}

public String sortString(String s) {
    int[] cnt = new int[26];
    for (int i = 0; i < s.length(); i++) {
        cnt[s.charAt(i) - 'a']++;
    }
    StringBuilder res = new StringBuilder();
    int total = s.length();
    while (res.length() < total) {
        // Ascending phase
        int last = -1;
        for (int i = 0; i < 26; i++) {
            if (cnt[i] > 0) {
                res.append((char) ('a' + i));
                cnt[i]--;
                last = i;
                break;
            }
        }
        if (last == -1) break;
        while (true) {
            int next = -1;
            for (int j = last + 1; j < 26; j++) {
                if (cnt[j] > 0) {
                    next = j;
                    break;
                }
            }
            if (next == -1) break;
            res.append((char) ('a' + next));
            cnt[next]--;
            last = next;
        }

        // Descending phase
        int lastDesc = -1;
        for (int i = 25; i >= 0; i--) {
            if (cnt[i] > 0) {
                res.append((char) ('a' + i));
                cnt[i]--;
                lastDesc = i;
                break;
            }
        }
        if (lastDesc == -1) break;
        while (true) {
            int prev = -1;
            for (int j = lastDesc - 1; j >= 0; j--) {
                if (cnt[j] > 0) {
                    prev = j;
                    break;
                }
            }
            if (prev == -1) break;
            res.append((char) ('a' + prev));
            cnt[prev]--;
            lastDesc = prev;
        }
    }
    return res.toString();
}

public String sortString(String s) {
    TreeMap<Character, Integer> map = new TreeMap<>();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        map.merge(c, 1, Integer::sum);
    }
    StringBuilder res = new StringBuilder();
    while (!map.isEmpty()) {
        // Ascending phase
        Character cur = map.firstKey();
        res.append(cur);
        int cnt = map.get(cur);
        if (cnt == 1) {
            map.remove(cur);
        } else {
            map.put(cur, cnt - 1);
        }
        while (!map.isEmpty()) {
            Character next = map.higherKey(cur);
            if (next == null) break;
            res.append(next);
            int ncnt = map.get(next);
            if (ncnt == 1) {
                map.remove(next);
            } else {
                map.put(next, ncnt - 1);
            }
            cur = next;
        }

        // Descending phase
        if (!map.isEmpty()) {
            cur = map.lastKey();
            res.append(cur);
            int cntd = map.get(cur);
            if (cntd == 1) {
                map.remove(cur);
            } else {
                map.put(cur, cntd - 1);
            }
            while (!map.isEmpty()) {
                Character prev = map.lowerKey(cur);
                if (prev == null) break;
                res.append(prev);
                int pcnt = map.get(prev);
                if (pcnt == 1) {
                    map.remove(prev);
                } else {
                    map.put(prev, pcnt - 1);
                }
                cur = prev;
            }
        }
    }
    return res.toString();
}

