    sets[0] = new java.util.HashSet<>();
    sets[0].add(0);

    for (int num : nums) {
        // traverse k in descending order to avoid using the same element multiple times in one iteration
        for (int k = n; k >= 1; k--) {
            if (sets[k - 1] == null) continue;
            java.util.HashSet<Integer> prev = sets[k - 1];
            java.util.HashSet<Integer> current = sets[k];
            if (current == null) current = new java.util.HashSet<>();
            for (int s : prev) {
                current.add(s + num);
            }
            sets[k] = current;
        }
    }

    // Check for each possible subset size k (1 <= k <= n/2)
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue; // target sum must be integer
        int target = (totalSum * k) / n;
        if (sets[k] != null && sets[k].contains(target)) {
            return true;
        }
    }
    return false;
}

