        int target = (total * k) / n;
        @SuppressWarnings("unchecked")
        java.util.HashSet<Integer>[] sets = new java.util.HashSet[k + 1];
        for (int i = 0; i <= k; i++) sets[i] = new java.util.HashSet<>();
