    int n = nums.length;
    if (n <= 1) return false;
    int total = 0;
    for (int v : nums) total += v;
    int half = n / 2;
    int N1 = half;
    int N2 = n - half;
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] sums1 = new HashSet[N1 + 1];
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] sums2 = new HashSet[N2 + 1];
    for (int i = 0; i <= N1; i++) sums1[i] = new HashSet<>();
    for (int i = 0; i <= N2; i++) sums2[i] = new HashSet<>();
    // subsets of first half
    for (int mask = 1; mask < (1 << N1); mask++) {
        int sum = 0;
        int cnt = 0;
        for (int i = 0; i < N1; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[i];
                cnt++;
            }
        }
        sums1[cnt].add(sum);
    }
    // subsets of second half
    for (int mask = 1; mask < (1 << N2); mask++) {
        int sum = 0;
        int cnt = 0;
        for (int i = 0; i < N2; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[N1 + i];
                cnt++;
            }
        }
        sums2[cnt].add(sum);
    }
    // try all possible split sizes
    for (int k = 1; k < n; k++) {
        if ((long) total * k % n != 0) continue;
        long target = (long) total * k / n;
        for (int i = 0; i <= k; i++) {
            int j = k - i;
            if (i > N1 || j > N2) continue;
            HashSet<Integer> set1 = sums1[i];
            HashSet<Integer> set2 = sums2[j];
            if (set1.isEmpty() || set2.isEmpty()) continue;
            for (int s1 : set1) {
                long need = target - s1;
                if (need < Integer.MIN_VALUE || need > Integer.MAX_VALUE) continue;
                if (set2.contains((int) need)) return true;
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    long totalSum = 0;
    for (int num : nums) totalSum += num;

    @SuppressWarnings("unchecked")
    java.util.HashSet<Long>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0L);

    for (int num : nums) {
        long val = num;
        for (int size = n - 1; size >= 0; size--) {
            if (dp[size].isEmpty()) continue;
            java.util.HashSet<Long> currentSet = dp[size];
            java.util.HashSet<Long> nextSet = dp[size + 1];
            for (Long sum : currentSet) {
                nextSet.add(sum + val);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        long target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return 0;
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int current = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int cur = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = cur;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int costFromOneStepBack = dp[i - 1] + cost[i - 1];
        int costFromTwoStepsBack = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(costFromOneStepBack, costFromTwoStepsBack);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);
    int first = cost[0];
    int second = cost[1];
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(first, second);
        first = second;
        second = curr;
    }
    return Math.min(first, second);
}

