public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    int total = 1 << k;
    if (n < total) return false;
    boolean[] seen = new boolean[total];
    int mask = 0;
    int maskLimit = total - 1;
    for (int i = 0; i < n; i++) {
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen[mask] = true;
        }
    }
    for (boolean b : seen) {
        if (!b) return false;
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k <= 0) return true;
    if (n < k) return false;
    int total = 1 << k;          // number of possible k-length codes
    boolean[] seen = new boolean[total];
    int mask = total - 1;        // mask to keep only k bits

    // Build the first code of length k
    int code = 0;
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int count = 1;

    // Slide through the string
    for (int i = k; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == total) return true; // all codes found early
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return true; // Trivial case: empty code set
    int n = s.length();
    if (n < k) return false; // Cannot contain all codes of length k

    int totalCodes = 1 << k;
    boolean[] seen = new boolean[totalCodes];
    int seenCount = 0;
    int mask = 0;
    int maskBits = totalCodes - 1; // bitmask to keep only k bits

    for (int i = 0; i < n; i++) {
        // Build current window mask
        mask = ((mask << 1) & maskBits) | (s.charAt(i) - '0');
        if (i >= k - 1) { // Window of length k is ready
            if (!seen[mask]) {
                seen[mask] = true;
                seenCount++;
                if (seenCount == totalCodes) {
                    return true; // All codes found early
                }
            }
        }
    }
    return false; // End of string, not all codes found
}

public boolean hasAllCodes(String s, int k) {
