public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    java.util.ArrayList<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int size = fib.size();
        int next = fib.get(size - 1) + fib.get(size - 2);
        if (next > k) break;
        fib.add(next);
    }
    // Greedy subtraction from the largest Fibonacci number
    int count = 0;
    while (k > 0) {
        for (int i = fib.size() - 1; i >= 0; i--) {
            int f = fib.get(i);
            if (f <= k) {
                k -= f;
                count++;
                break;
            }
        }
    }
    return count;
}

