public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        twos |= ones & num;
        ones ^= num;
        int commonMask = ~(ones & twos);
        ones &= commonMask;
        twos &= commonMask;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int cnt = 0;
        for (int num : nums) {
            cnt += (num >> i) & 1;
        }
        if ((cnt % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

