}

public static int singleNumber(int[] nums) {
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            // Check if the i-th bit is set in num
            if (((num >> i) & 1) == 1) {
                bitCount[i]++;
            }
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        // If the number of set bits at position i is not a multiple of 3,
        // then this bit belongs to the unique number.
        if ((bitCount[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    int result = 0;
    for (int bit = 0; bit < 32; bit++) {
        int sum = 0;
        int mask = 1 << bit;
        for (int num : nums) {
            if ((num & mask) != 0) {
                sum++;
            }
        }
        if ((sum % 3) != 0) {
            result |= mask;
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    if (low > high) return new ArrayList<>();
    TreeSet<Integer> result = new TreeSet<>();
    Queue<Long> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        if (i >= low && i <= high) result.add(i);
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) continue;
        int lastDigit = (int) (num % 10);
        // Append digit - 1
        int nextDigit = lastDigit - 1;
        if (nextDigit >= 0) {
            long nextNum = num * 10 + nextDigit;
            if (nextNum <= high) {
                if (nextNum >= low) result.add((int) nextNum);
                queue.offer(nextNum);
            }
        }
        // Append digit + 1
        nextDigit = lastDigit + 1;
        if (nextDigit <= 9) {
            long nextNum = num * 10 + nextDigit;
            if (nextNum <= high) {
                if (nextNum >= low) result.add((int) nextNum);
                queue.offer(nextNum);
            }
        }
    }
    return new ArrayList<>(result);
}

public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low > high) return result;
    if (low <= 0 && 0 <= high) result.add(0);
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int d = 1; d <= 9; d++) {
        queue.add((long) d);
    }
    while (!queue.isEmpty()) {
        long cur = queue.poll();
        if (cur > high) continue;
        if (cur >= low) result.add((int) cur);
        long lastDigit = cur % 10;
        for (int diff = -1; diff <= 1; diff += 2) {
            int nextDigit = (int) lastDigit + diff;
            if (nextDigit < 0 || nextDigit > 9) continue;
            long nextNum = cur * 10 + nextDigit;
            if (nextNum <= high) {
                queue.add(nextNum);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

