public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    // Include 0 if within range
    if (low == 0) {
        result.add(0);
    }

    Queue<Long> queue = new LinkedList<>();
    // Initialize queue with numbers 1-9
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long current = queue.poll();
        if (current > high) {
            continue;
        }

        if (current >= low) {
            result.add((int) current);
        }

        long lastDigit = current % 10;

        if (lastDigit > 0) {
            long newNum = current * 10 + (lastDigit - 1);
            if (newNum <= high) {
                queue.offer(newNum);
            }
        }

        if (lastDigit < 9) {
            long newNum = current * 10 + (lastDigit + 1);
            if (newNum <= high) {
                queue.offer(newNum);
            }
        }
    }

    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) return 0;
    long count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long lower  = n % factor;
        long cur    = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
    }
    return (int) count;
}

