    int m = mat.length;
    int n = mat[0].length;
    int[][][] dp = new int[4][m][n]; // 0: horizontal, 1: vertical, 2: diagonal, 3: anti-diagonal
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[0][i][j] = (j > 0 ? dp[0][i][j - 1] : 0) + 1; // horizontal
