        int group = absValue % 1000;
        absValue /= 1000;
        if (absValue > 0) {
            sb.insert(0, String.format("%03d", group));
            sb.insert(0, '.');
        } else {
            sb.insert(0, Integer.toString(group));
        }
    }
    if (negative) {
