public static int squarePermutations(int[] A) {

    int n=A.length;
    if (n==0) return 1;
    boolean[][] good=new boolean[n][n];
    for (int i=0;i<n;i++){
        for (int j=0;j<n;j++){
            if (i==j) continue; // adjacency between same index? in permutation cannot equal? Actually we cannot use same index twice since permutation elements correspond one time each, so adjacency only when i != j. But adjacency doesn't need to exclude same because we won't use same index again.
            int sum=A[i]+A[j];
            int r=(int)Math.round(Math.sqrt(sum));
            good[i][j]=(r*r==sum);
        }
    }
    int maxMask=1<<n;
    long[][] dp=new long[maxMask][n];
    for (int i=0;i<n;i++){
        dp[1<<i][i]=1;
    }
    for (int mask=1;mask<maxMask;mask++){
        for (int last=0;last<n;last++){
            if (((mask>>last)&1)==0) continue;
            long cur=dp[mask][last];
            if (cur==0) continue;
            for (int next=0;next<n;next++){
                if ((mask>>next &1)==1) continue;
                if (!good[last][next]) continue;
                // skip duplicates
                boolean skip=false;
                for (int k=0;k<next;k++){
                    if (((mask>>k)&1)==0 && A[k]==A[next]){
                        skip=true;break;
                    }
                }
                if (skip) continue;
                dp[mask | (1<<next)][next] += cur;
            }
        }
    }
    long ans=0;
    int fullMask=maxMask-1;
    for (int i=0;i<n;i++){
        ans+=dp[fullMask][i];
    }
    return (int)ans;
}

