private static void dfs(char[] buf, int left, int right, int n, List<String> result){
    if (left > right){
        result.add(new String(buf));
        return;
    }
    if (left == right){
        char[] mid = {'0','1','8'};
        for (char c : mid){
            buf[left] = c;
            dfs(buf, left+1, right-1, n, result);
        }
    } else {
        char[][] pairs = {{'0','0'},{'1','1'},{'6','9'},{'8','8'},{'9','6'}};
        for (char[] p : pairs){
            if (left == 0 && n > 1 && p[0] == '0') continue;
            buf[left] = p[0];
            buf[right] = p[1];
            dfs(buf, left+1, right-1, n, result);
        }
    }
}

