private static List<String> findStrobogrammatic(int currLen, int totalLen) {
    List<String> result = new ArrayList<>();
    if (currLen == 0) {
        result.add("");
        return result;
    }
    if (currLen == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    List<String> sub = findStrobogrammatic(currLen - 2, totalLen);
    char[][] pairs = {{'0','0'},{'1','1'},{'6','9'},{'8','8'},{'9','6'}};
    for (String middle : sub) {
        for (char[] pair : pairs) {
            if (currLen == totalLen && pair[0] == '0') {
                continue; // avoid leading zero
            }
            result.add(pair[0] + middle + pair[1]);
        }
    }
    return result;
}

