public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(n);
    long current = 1;
    for (int count = 0; count < n; count++) {
        result.add((int) current);
        if (current * 10 <= n) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(n);
    int cur = 1;
    for (int i = 0; i < n; i++) {
        result.add(cur);
        if ((long)cur * 10 <= n) {
            cur *= 10;
        } else if (cur % 10 != 9 && cur + 1 <= n) {
            cur++;
        } else {
            while (cur / 10 % 10 == 9) {
                cur /= 10;
            }
            cur = cur / 10 + 1;
        }
    }
    return result;
}

